mapper.select:
SELECT u.id, u.username, u.password, u.real_name, u.gender, u.birthday, u.phone, u.email, u.avatar, u.id_card, u.balance, u.role_code, u.status, u.created_by, u.creation_date, u.modify_by, u.modify_date, r.role_name FROM sys_user u LEFT JOIN sys_role r ON u.role_code = r.role_code
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND u.role_code = #{roleCode}
AND u.status = #{status}
ORDER BY u.id ASC LIMIT #{offset}, #{pageSize}

SELECT COUNT(1) FROM sys_user u
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND u.role_code = #{roleCode}
AND u.status = #{status}

mapper.update:
UPDATE sys_user
real_name = #{realName}, gender = #{gender}, birthday = #{birthday}, phone = #{phone}, email = #{email}, avatar = #{avatar}, id_card = #{idCard}, role_code = #{roleCode}, status = #{status}, modify_by = #{modifyBy}, modify_date = NOW()
WHERE id = #{id}
